      orgs = await prisma.organization.findMany({
        orderBy: { name: 'asc' },
        select: { id: true, name: true, code: true },
      });
    } else if (user.organizationId) {
      const org = await prisma.organization.findUnique({
        where: { id: user.organizationId },
        select: { id: true, name: true, code: true },
      });
      if (org) orgs = [org];
    }

    res.json({
      success: true,
      data: orgs.map((org) => ({
        id: org.id,
        name: org.name,
        code: org.code,
        role: user.role,
      })),
    });
