      const sub = submissions.find((s) => s.assignmentId === a.id);
      return {
        id: a.id,
        title: a.title,
        subject: a.subject,
        dueDate: a.dueDate,
        totalMarks: a.totalMarks,
        duration: a.duration,
        attemptStatus: sub ? sub.status : 'AVAILABLE',
        submittedAt: sub?.submittedAt || null,
      };
    });

    res.json({ success: true, data });
  } catch (error: any) {
