  action: string;
  entity?: string;
  entityId?: string;
  ipAddress?: string;
  userAgent?: string;
  metadata?: Record<string, any>;
}

export class AuditService {
  static async logAuditEvent(payload: AuditLogPayload): Promise<void> {
    try {
      await prisma.auditLog.create({
        data: {
          userId: payload.userId || null,
          action: payload.action,
          entity: payload.entity || null,
          entityId: payload.entityId || null,
          ipAddress: payload.ipAddress || 'unknown',
          userAgent: payload.userAgent || 'unknown',
          metadata: payload.metadata ? payload.metadata : undefined,
        },
      });
    } catch (error) {
      logger.error(`[AuditService] Failed to log event: ${error}`);
    }
  }

  static async logAction(data: {
    userId?: string;
    action: string;
    ipAddress?: string;
    userAgent?: string;
    metadata?: any;
  }) {
    try {
      return await prisma.auditLog.create({
        data: {
          userId: data.userId || null,
          action: data.action,
          ipAddress: data.ipAddress || '127.0.0.1',
          userAgent: data.userAgent || 'unknown',
          metadata: data.metadata || {},
        },
      });
    } catch (error) {
      logger.error(`[AuditService] Failed to log action: ${error}`);
      throw error;
    }
  }

  static async getLogs(filters?: {
    userId?: string;
    action?: string;
    startDate?: string;
    endDate?: string;
    limit?: number;
    skip?: number;
  }) {
    const limit = filters?.limit || 50;
    const skip = filters?.skip || 0;

    const where: any = {};
    if (filters?.userId) where.userId = filters.userId;
    if (filters?.action) where.action = filters.action;
    if (filters?.startDate || filters?.endDate) {
      where.createdAt = {};
      if (filters.startDate) where.createdAt.gte = new Date(filters.startDate);
      if (filters.endDate) where.createdAt.lte = new Date(filters.endDate);
    }

    return prisma.auditLog.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: limit,
      skip,
    });
  }
}

import jwt from 'jsonwebtoken';
import argon2 from 'argon2';
import crypto from 'crypto';
import prisma from '../config/prisma';
import { env } from '../config/env';
import { logger } from '../utils/logger';

const ACCESS_TOKEN_EXPIRY = '15m';
const REFRESH_TOKEN_EXPIRY_DAYS = 30;

export interface TokenPayload {
  userId: string;
  email: string;
  role: string;
  organizationId?: string | null;
  activeOrganizationId?: string | null;
  departmentId?: string | null;
}

export class AuthError extends Error {
  constructor(public status: number, message: string) {
    super(message);
    this.name = 'AuthError';
  }
}

/**
 * Hash password with Argon2
 */
export async function hashPassword(password: string): Promise<string> {
  return argon2.hash(password);
}

/**
 * Verify password
 */
export async function verifyPassword(password: string, hash: string): Promise<boolean> {
  try {
    return await argon2.verify(hash, password);
  } catch (err) {
    logger.error(`[verifyPassword] Error: ${err}`);
    return false;
  }
}

/**
 * Generate cryptographic random token hash
 */
export function generateRandomToken(): string {
  return crypto.randomBytes(40).toString('hex');
}

/**
 * Generate Access Token (JWT)
 */
export function generateAccessToken(payload: TokenPayload): string {
  return jwt.sign(
    {
      id: payload.userId,
      email: payload.email,
      role: payload.role,
      organizationId: payload.organizationId,
      activeOrganizationId: payload.activeOrganizationId,
      departmentId: payload.departmentId,
    },
    env.JWT_SECRET,
    { expiresIn: ACCESS_TOKEN_EXPIRY }
  );
}

/**
 * Verify Access Token (JWT)
 */
export function verifyAccessToken(token: string): TokenPayload {
  try {
    const decoded = jwt.verify(token, env.JWT_SECRET) as any;
    return {
      userId: decoded.id,
      email: decoded.email,
      role: decoded.role,
      organizationId: decoded.organizationId,
      activeOrganizationId: decoded.activeOrganizationId,
      departmentId: decoded.departmentId,
    };
  } catch (err) {
    if (err instanceof jwt.TokenExpiredError) {
      throw new AuthError(401, 'Access token has expired');
    }
    throw new AuthError(401, 'Invalid access token');
  }
}

/**
 * Create a new Refresh Token in the database
 */
export async function createRefreshToken(userId: string): Promise<string> {
  const rawToken = generateRandomToken();
  const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');
  const expiresAt = new Date();
  expiresAt.setDate(expiresAt.getDate() + REFRESH_TOKEN_EXPIRY_DAYS);

  await prisma.refreshToken.create({
    data: {
      tokenHash,
      userId,
      expiresAt,
    },
  });

  return rawToken;
}

/**
 * Rotate Refresh Token (implements reuse detection)
 */
export async function rotateRefreshToken(rawToken: string): Promise<{ accessToken: string; newRefreshToken: string }> {
  const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');

  const record = await prisma.refreshToken.findUnique({
    where: { tokenHash },
    include: { user: true },
  });

  if (!record) {
    throw new AuthError(401, 'Invalid refresh token');
  }

  // REUSE DETECTION: If token is already revoked, revoke all tokens for this user!
  if (record.isRevoked || record.expiresAt < new Date()) {
    await prisma.refreshToken.updateMany({
      where: { userId: record.userId },
      data: { isRevoked: true },
    });
    await prisma.session.updateMany({
      where: { userId: record.userId },
      data: { isActive: false },
    });
    logger.warn(`[REUSE_DETECTION] Revoked refresh token reuse detected for userId=${record.userId}. Revoking all sessions.`);
    throw new AuthError(401, 'Refresh token reuse detected. All sessions terminated.');
  }

  // Revoke current token
  await prisma.refreshToken.update({
    where: { id: record.id },
    data: { isRevoked: true },
  });

  // Create new refresh token and access token
  const newRefreshToken = await createRefreshToken(record.userId);
  const accessToken = generateAccessToken({
    userId: record.userId,
    email: record.user.email,
    role: record.user.role,
      organizationId: record.user.organizationId,
      activeOrganizationId: record.user.activeOrganizationId,
      departmentId: record.user.departmentId,
  });

  return { accessToken, newRefreshToken };
}

/**
 * Terminate Session
 */
export async function revokeSession(rawToken: string): Promise<void> {
  const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');
  await prisma.refreshToken.updateMany({
    where: { tokenHash },
    data: { isRevoked: true },
  });
}

import type { CanonicalGenerationState, CanonicalPaperMetadata } from '../types/canonical.types';
import type { ValidatedPaper } from '../validators/paper.validator';

function computeRequestedFromAssignment(assignment: any): {
  requestedMarks: number;
  requestedQuestionCount: number;
} {
  const requestedMarks = assignment.totalMarks ?? 0;
  const requestedQuestionCount = assignment.questionConfig?.count ?? 0;
  return { requestedMarks, requestedQuestionCount };
}

type PaperLike = { sections: any[]; pdfUrl?: string; duration?: number } | Pick<ValidatedPaper, 'sections'>;

function computeGeneratedFromPaper(paper: PaperLike | null): {
  generatedMarks: number;
  generatedQuestionCount: number;
  answerKeyReady: boolean;
  sections: CanonicalPaperMetadata['sections'];
} {
  if (!paper) {
    return {
      generatedMarks: 0,
      generatedQuestionCount: 0,
      answerKeyReady: false,
      sections: [],
    };
  }

  const sections = (paper.sections ?? []).map((section: any) => {
    const sectionMarks = (section.questions ?? []).reduce((sum: number, q: any) => sum + (q.marks ?? 0), 0);
    return {
      title: section.title,
      questionCount: section.questions.length,
      marks: sectionMarks,
    };
  });

  const questions = (paper.sections ?? []).flatMap((s: any) => s.questions ?? []);
  const generatedQuestionCount = questions.length;
  const generatedMarks = questions.reduce((sum: number, q: any) => sum + (q.marks ?? 0), 0);
  const answerKeyReady = generatedQuestionCount > 0 && questions.every((q) => Boolean(q.answer?.text?.trim()));

  return { generatedMarks, generatedQuestionCount, answerKeyReady, sections };
}

function clampProgress(value: number): number {
  return Math.max(0, Math.min(100, Math.round(value)));
}

export function buildCanonicalPaperMetadata(
  assignment: any,
  paper: any | null
): CanonicalPaperMetadata {
  const { requestedMarks, requestedQuestionCount } = computeRequestedFromAssignment(assignment);
  const generated = computeGeneratedFromPaper(paper);

  return {
    title: assignment.title,
    subject: assignment.subject,
    className: assignment.className ?? 'Not Specified',
    durationMinutes: assignment.duration ?? paper?.duration ?? 45,
    requestedMarks,
    generatedMarks: generated.generatedMarks,
    requestedQuestionCount,
    generatedQuestionCount: generated.generatedQuestionCount,
    schoolName: assignment.schoolName ?? 'School',
    sections: generated.sections,
    answerKeyReady: generated.answerKeyReady,
    pdfReady: Boolean(paper?.pdfUrl),
  };
}

export function buildCanonicalGenerationState(input: {
  assignment: any;
  paper: any | null;
  job: any | null;
}): CanonicalGenerationState {
  const { assignment, paper, job } = input;
  const canonicalMetadata = buildCanonicalPaperMetadata(assignment, paper);

  const stage = (job?.status ?? (assignment.status === 'draft' ? 'queued' : 'extracting_content')) as CanonicalGenerationState['stage'];
  const progress = assignment.status === 'completed'
    ? 100
    : assignment.status === 'failed'
    ? clampProgress(job?.progress ?? 0)
    : clampProgress(job?.progress ?? 0);

  const completionPercentage =
    canonicalMetadata.requestedQuestionCount > 0
      ? clampProgress((canonicalMetadata.generatedQuestionCount / canonicalMetadata.requestedQuestionCount) * 100)
      : 0;

  const generationStatus =
    assignment.status === 'draft'
      ? 'draft'
      : assignment.status === 'queued' || assignment.status === 'generating'
      ? 'generating'
      : (assignment.status as CanonicalGenerationState['generationStatus']);

  return {
    canonicalMetadata,
    progress,
    stage,
    generatedQuestions: canonicalMetadata.generatedQuestionCount,
    requestedQuestions: canonicalMetadata.requestedQuestionCount,
    generatedMarks: canonicalMetadata.generatedMarks,
    requestedMarks: canonicalMetadata.requestedMarks,
    completionPercentage,
    answerKeyReady: canonicalMetadata.answerKeyReady,
    pdfReady: canonicalMetadata.pdfReady,
    generationStatus,
  };
}

import prisma from '../config/prisma';

export class ChatService {
  /**
   * Save a message to the database
   */
  static async saveMessage(
    conversationId: string,
    senderId: string,
    message: string,
    attachments: any[] = []
  ) {
    return prisma.message.create({
      data: {
        conversationId,
        senderId,
        message,
        attachments,
      },
      include: {
        sender: { select: { id: true, firstName: true, lastName: true, role: true } },
      },
    });
  }

  /**
   * Fetch chat history for a conversation
   */
  static async getMessages(conversationId: string, limit: number = 50, cursor?: string) {
    return prisma.message.findMany({
      where: { conversationId },
      take: limit,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      orderBy: { createdAt: 'asc' }, // Order asc for sequential rendering in chat bubbles
      include: {
        sender: { select: { id: true, firstName: true, lastName: true, role: true } },
      },
    });
  }

  /**
   * Get all users in the same organization, excluding the current user
   */
  static async getOrgUsers(organizationId: string | null, currentUserId: string) {
    if (!organizationId) {
      // In development, if organizationId is not set, return all other active users
      return prisma.user.findMany({
        where: {
          id: { not: currentUserId },
          status: 'ACTIVE',
        },
        select: {
          id: true,
          firstName: true,
          lastName: true,
          email: true,
          role: true,
        },
        orderBy: [
          { firstName: 'asc' },
          { lastName: 'asc' },
        ],
      });
    }

    return prisma.user.findMany({
      where: {
        organizationId,
        id: { not: currentUserId },
        status: 'ACTIVE',
      },
      select: {
        id: true,
        firstName: true,
        lastName: true,
        email: true,
        role: true,
      },
      orderBy: [
        { firstName: 'asc' },
        { lastName: 'asc' },
      ],
    });
  }

  /**
   * List all conversations (chats) that the current user has interacted in
   */
  static async getConversations(userId: string) {
    // 1. Get all group IDs the user belongs to
    const memberships = await prisma.groupMember.findMany({
      where: { userId },
      select: { groupId: true }
    });
    const groupIds = memberships.map(m => m.groupId);

    // 2. Find unique conversationIds where user is participating
    const messages = await prisma.message.findMany({
      where: {
        OR: [
          { conversationId: { in: groupIds } },
          {
            AND: [
              { conversationId: { startsWith: 'dm_' } },
              { conversationId: { contains: userId } }
            ]
          }
        ]
      },
      orderBy: { createdAt: 'desc' },
      distinct: ['conversationId'],
      include: {
        sender: {
          select: {
            id: true,
            firstName: true,
            lastName: true,
            role: true
          }
        }
      }
    });

    // 3. Populate details for each conversation (recipient name/avatar for DMs, group names for Groups)
    const conversations = await Promise.all(messages.map(async (msg) => {
      const isDM = msg.conversationId.startsWith('dm_');
      let name = '';
      let recipientId = '';
      let role = '';

      if (isDM) {
        const ids = msg.conversationId.replace('dm_', '').split('_');
        const otherId = ids.find(id => id !== userId) || '';
        recipientId = otherId;

        const otherUser = await prisma.user.findUnique({
          where: { id: otherId },
          select: { firstName: true, lastName: true, role: true }
        });

        if (otherUser) {
          name = `${otherUser.firstName} ${otherUser.lastName}`;
          role = otherUser.role;
        } else {
          name = 'Unknown Builder';
        }
      } else {
        const group = await prisma.communityGroup.findUnique({
          where: { id: msg.conversationId },
          select: { name: true }
        });
        name = group?.name || 'Unknown Group';
      }

      return {
        id: msg.conversationId,
        name,
        isDM,
        recipientId,
        role,
        lastMessage: msg.message,
        lastMessageTime: msg.createdAt,
        unreadCount: 0
      };
    }));

    return conversations;
  }
}

import prisma from '../config/prisma';


export class CommunityService {
  /**
   * List community groups visible to the current user.
   */
  static async getGroups(organizationId: string | undefined, userId: string) {
    const groups = await prisma.communityGroup.findMany({
      where: {
        OR: [
          { type: 'PUBLIC' },
          ...(organizationId ? [{ organizationId }] : []),
        ],
      },
      orderBy: { createdAt: 'desc' },
      include: {
        owner: { select: { id: true, firstName: true, lastName: true } },
        members: {
          select: { userId: true },
        },
        _count: {
          select: { members: true },
        },
      },
    });

    return groups.map((group) => ({
      id: group.id,
      name: group.name,
      description: group.description,
      type: group.type,
      avatar: group.avatar,
      owner: group.owner,
      organizationId: group.organizationId,
      createdAt: group.createdAt,
      memberCount: group._count.members,
      isMember: group.members.some((member) => member.userId === userId),
    }));
  }

  /**
   * Create a new community post
   */
  static async createPost(
    authorId: string,
    content: string,
    type: string,
    visibility: string,
    attachments: any[] = [],
    organizationId?: string,
    title?: string,
    tags?: string[]
  ) {
    return prisma.communityPost.create({
      data: {
        authorId,
        title,
        content,
        type,
        visibility,
        attachments,
        tags: tags ?? [],
        organizationId,
      },
      include: {
        author: { select: { id: true, firstName: true, lastName: true, role: true } },
      },
    });
  }

  /**
   * Fetch a feed of posts
   */
  static async getFeed(organizationId?: string, limit: number = 20, cursor?: string) {
    const whereClause: any = {};
    if (organizationId) {
      whereClause.OR = [
        { visibility: 'PUBLIC' },
        { organizationId, visibility: 'ORG_ONLY' },
      ];
    } else {
      whereClause.visibility = 'PUBLIC';
    }

    return prisma.communityPost.findMany({
      where: whereClause,
      take: limit,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      orderBy: { createdAt: 'desc' },
      include: {
        author: { select: { id: true, firstName: true, lastName: true, role: true } },
      },
    });
  }

  /**
   * Create a community group
   */
  static async createGroup(
    ownerId: string,
    name: string,
    description: string,
    type: string,
    organizationId?: string
  ) {
    return prisma.communityGroup.create({
      data: {
        name,
        description,
        type,
        ownerId,
        organizationId,
        members: {
          create: [{ userId: ownerId, role: 'OWNER' }],
        },
      },
      include: {
        owner: { select: { id: true, firstName: true, lastName: true } },
      },
    });
  }

  /**
   * Join a community group
   */
  static async joinGroup(groupId: string, userId: string) {
    const group = await prisma.communityGroup.findUnique({ where: { id: groupId } });
    if (!group) throw new Error('Group not found');
    if (group.type === 'INVITE_ONLY') throw new Error('Group is invite-only');

    return prisma.groupMember.upsert({
      where: {
        groupId_userId: {
          groupId,
          userId,
        },
      },
      update: {},
      create: {
        groupId,
        userId,
        role: 'MEMBER',
      },
      include: {
        user: { select: { id: true, firstName: true, lastName: true } },
      },
    });
  }
}

import { createInvitation } from './invitation.service';
import prisma from '../config/prisma';
import { logger } from '../utils/logger';
import { SystemRole } from '@prisma/client';

export interface CsvImportReport {
  created: number;
  skipped: number;
  duplicates: number;
  invalidEmails: number;
  errors: Array<{ row: number; email: string; error: string }>;
}

export const processCsvImport = async (csvData: string, organizationId: string, createdById: string): Promise<CsvImportReport> => {
  const lines = csvData.split('\n').filter(line => line.trim() !== '');
  const report: CsvImportReport = {
    created: 0,
    skipped: 0,
    duplicates: 0,
    invalidEmails: 0,
    errors: []
  };

  if (lines.length < 2) return report; // No data rows

  const headers = lines[0].toLowerCase().split(',').map(h => h.trim());
  const emailIdx = headers.indexOf('email');
  const roleIdx = headers.indexOf('role');

  if (emailIdx === -1 || roleIdx === -1) {
    throw new Error('CSV must contain "email" and "role" columns.');
  }

  // Pre-fetch existing emails to quickly check duplicates
  const existingUsers = await prisma.user.findMany({ select: { email: true } });
  const existingEmails = new Set(existingUsers.map(u => u.email.toLowerCase()));

  const pendingInvitations = await prisma.invitation.findMany({ where: { status: 'PENDING' }, select: { email: true } });
  const pendingEmails = new Set(pendingInvitations.map(i => i.email.toLowerCase()));

  for (let i = 1; i < lines.length; i++) {
    const columns = lines[i].split(',').map(col => col.trim());
    if (columns.length < headers.length) continue;

    const email = columns[emailIdx].toLowerCase();
    const roleStr = columns[roleIdx].toUpperCase();

    // Basic email validation
    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      report.invalidEmails++;
      report.errors.push({ row: i, email, error: 'Invalid email format' });
      continue;
    }

    if (existingEmails.has(email)) {
      report.duplicates++;
      report.errors.push({ row: i, email, error: 'User already exists' });
      continue;
    }

    if (!['TEACHER', 'STUDENT', 'ADMIN'].includes(roleStr)) {
      report.skipped++;
      report.errors.push({ row: i, email, error: `Invalid role: ${roleStr}` });
      continue;
    }

    try {
      await createInvitation({
        email,
        role: roleStr as SystemRole,
        organizationId,
        createdById
      });
      report.created++;
      pendingEmails.add(email);
    } catch (err: any) {
      report.skipped++;
      report.errors.push({ row: i, email, error: err.message });
      logger.error(`[CSV Import] Error creating invite for ${email}: ${err.message}`);
    }
  }

  return report;
};

import fs from 'fs/promises';
import pdfParse from 'pdf-parse';
import prisma from '../config/prisma';
import { callAI } from './question-generation.service';
import { logger } from '../utils/logger';

export async function extractTextFromFile(filePath: string, mimeType: string): Promise<string> {
  if (mimeType === 'application/pdf') {
    const buffer = await fs.readFile(filePath);
    const parsed = await pdfParse(buffer);
    return parsed.text || '';
  } else if (mimeType === 'text/plain') {
    return await fs.readFile(filePath, 'utf-8');
  }
  // Fallback for DOCX/other types
  return await fs.readFile(filePath, 'utf-8').catch(() => '');
}

export async function evaluateSubmission(submissionId: string): Promise<any> {
  const submission = await prisma.studentSubmission.findUnique({
    where: { id: submissionId },
  });

  if (!submission) {
    throw new Error('Submission not found');
  }

  // Get Assignment config
  const config = await prisma.assignmentGradingConfig.findUnique({
    where: { assignmentId: submission.assignmentId },
    include: { rubric: { include: { criteria: true } } },
  });

  if (!config) {
    throw new Error('Grading configuration not found for this assignment');
  }

  const studentAnswerText = await extractTextFromFile(submission.fileUrl, submission.fileType);

  const rubricPrompt = config.rubric
    ? `Use the following Rubric Criteria to evaluate the student's submission:\n` +
      config.rubric.criteria.map((c) => `- ${c.name} (Max Marks: ${c.maxMarks}): ${c.description}`).join('\n')
    : 'No rubric provided. Evaluate overall correctness.';

  const systemPrompt = `You are an expert AI Assignment Grader. Your task is to evaluate a student's submission against an answer key and optionally a rubric.

Rules:
- Be fair and detailed.
- Check accuracy, completeness, structure, and grammar.
- Provide a score and explanation for each rubric criterion.
- Output ONLY valid JSON containing a score, total marks, general feedback, and criterion-by-criterion breakdown.
- Output format:
{
  "score": 85,
  "totalMarks": 100,
  "generalFeedback": "Excellent work overall...",
  "criteriaGrades": [
    {
      "criteriaId": "some-id",
      "name": "Accuracy",
      "score": 25,
      "explanation": "Correct use of concepts..."
    }
  ]
}`;

  const prompt = `
Answer Key:
${config.answerKeyText}

Rubric:
${rubricPrompt}

Student Submission:
${studentAnswerText}

Evaluate the submission and return the structured JSON.`;

  logger.info({ submissionId }, 'AI Assignment Evaluation started');

  try {
    const rawResult = await callAI(prompt, systemPrompt);
    const jsonMatch = rawResult.match(/\{[\s\S]*\}/);
    if (!jsonMatch) {
      throw new Error('No JSON output returned by LLM');
    }
    const data = JSON.parse(jsonMatch[0]);

    // Save evaluation to database
    const evaluation = await prisma.submissionEvaluation.upsert({
      where: { submissionId },
      create: {
        submissionId,
        score: Number(data.score) || 0,
        totalMarks: Number(data.totalMarks) || 100,
        generalFeedback: data.generalFeedback || '',
        criteriaGrades: data.criteriaGrades || [],
      },
      update: {
        score: Number(data.score) || 0,
        totalMarks: Number(data.totalMarks) || 100,
        generalFeedback: data.generalFeedback || '',
        criteriaGrades: data.criteriaGrades || [],
      },
    });

    await prisma.studentSubmission.update({
      where: { id: submissionId },
      data: { status: 'GRADED' },
    });

    logger.info({ submissionId, score: evaluation.score }, 'AI Assignment Evaluation completed');
    return evaluation;
  } catch (error) {
    logger.error(error, `AI Assignment Evaluation failed for submissionId: ${submissionId}`);
    throw error;
  }
}

