import { AccessToken } from 'livekit-server-sdk';
import prisma from '../config/prisma';

export class VoiceService {
  static async createVoiceRoom(name: string, type: string, createdById: string, organizationId?: string) {
    try {
      return prisma.voiceRoom.create({
        data: { name, type, createdById, organizationId },
        include: {
          createdBy: { select: { id: true, firstName: true, lastName: true } },
          _count: { select: { participants: { where: { leftAt: null } } } },
        },
      });
    } catch (err: any) {
      if (err.code === 'P2002') {
        throw new Error('A voice room with this name already exists');
      }
      throw err;
    }
  }

  static async getActiveRooms(organizationId?: string) {
    try {
      const rooms = await prisma.voiceRoom.findMany({
        where: {
          isActive: true,
          ...(organizationId && { organizationId }),
        },
        include: {
          createdBy: { select: { id: true, firstName: true, lastName: true } },
          participants: {
            where: { leftAt: null },
            include: { user: { select: { id: true, firstName: true, lastName: true } } },
          },
          _count: { select: { participants: { where: { leftAt: null } } } },
        },
        orderBy: { createdAt: 'desc' },
      });

      return rooms.map(room => ({
        id: room.id,
        name: room.name,
        type: room.type,
        isActive: room.isActive,
        createdAt: room.createdAt,
        createdBy: room.createdBy,
        organizationId: room.organizationId,
        participantCount: room._count.participants,
        participants: room.participants.map(p => ({
          userId: p.userId,
          name: `${p.user.firstName} ${p.user.lastName}`,
          joinedAt: p.joinedAt,
        })),
      }));
    } catch (err) {
      console.error('[VoiceService] Error fetching active rooms:', err);
      throw new Error('Failed to fetch active rooms');
    }
  }

  static async joinRoom(roomId: string, userId: string) {
    try {
      // Verify room exists and is active
      const room = await prisma.voiceRoom.findUnique({ where: { id: roomId } });
      if (!room) throw new Error('Room not found');
      if (!room.isActive) throw new Error('Room is no longer active');

      // Upsert: re-join if they left before
      return prisma.voiceRoomParticipant.upsert({
        where: { roomId_userId: { roomId, userId } },
        update: { leftAt: null, joinedAt: new Date() },
        create: { roomId, userId },
      });
    } catch (err: any) {
      console.error('[VoiceService] Error joining room:', err);
      throw err;
    }
  }

  static async leaveRoom(roomId: string, userId: string) {
    try {
      return prisma.voiceRoomParticipant.updateMany({
        where: { roomId, userId, leftAt: null },
        data: { leftAt: new Date() },
      });
    } catch (err: any) {
      console.error('[VoiceService] Error leaving room:', err);
      throw err;
    }
  }

  static async closeRoom(roomId: string, userId: string) {
    try {
      // Mark room inactive — only the creator can close
      const room = await prisma.voiceRoom.findUnique({ where: { id: roomId } });
      if (!room) throw new Error('Room not found');
      if (room.createdById !== userId) throw new Error('Only the creator can close a room');
      return prisma.voiceRoom.update({
        where: { id: roomId },
        data: { isActive: false },
      });
    } catch (err: any) {
      console.error('[VoiceService] Error closing room:', err);
      throw err;
    }
  }

  static generateToken(roomName: string, participantName: string, participantIdentity: string): Promise<string> {
    try {
      const apiKey = process.env.LIVEKIT_API_KEY || 'devkey';
      const apiSecret = process.env.LIVEKIT_API_SECRET || 'secret';

      const at = new AccessToken(apiKey, apiSecret, {
        identity: participantIdentity,
        name: participantName,
      });
      at.addGrant({ roomJoin: true, room: roomName, canPublish: true, canSubscribe: true });
      return Promise.resolve(at.toJwt());
    } catch (err: any) {
      console.error('[VoiceService] Error generating token:', err);
      throw new Error('Failed to generate voice room token');
    }
  }

  static getLiveKitUrl(): string {
    return process.env.LIVEKIT_URL || 'wss://vidyaai-2i2x11ot.livekit.cloud';
  }
}

import { Server as SocketIOServer } from 'socket.io';
import type { Server as HTTPServer } from 'http';
import type { ServerToClientEvents, ClientToServerEvents } from '../types/socket.types';
import { env } from '../config/env';
import { logger } from '../utils/logger';

let io: SocketIOServer<ClientToServerEvents, ServerToClientEvents> | null = null;
const ASSIGNMENT_ID_RE = /^[a-f\d]{24}$/i;
const SUBSCRIBE_WINDOW_MS = 10_000;
const MAX_SUBSCRIBES_PER_WINDOW = 30;
const MAX_ROOMS_PER_SOCKET = 50;

function isValidAssignmentId(value: unknown): value is string {
  return typeof value === 'string' && ASSIGNMENT_ID_RE.test(value.trim());
}

function parseOrigins(raw: string): string[] {
  return raw
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => s.replace(/\/+$/, ''));
}

function isAllowedVercelPreview(hostname: string): boolean {
  return /^vedaai[\w-]*\.vercel\.app$/i.test(hostname);
}

function isAllowedSocketOrigin(origin: string, allowedOrigins: string[]): boolean {
  const normalized = origin.replace(/\/+$/, '');
  if (allowedOrigins.includes(normalized)) return true;
  try {
    return isAllowedVercelPreview(new URL(normalized).hostname);
  } catch {
    return false;
  }
}

export function initializeSocketServer(
  httpServer: HTTPServer
): SocketIOServer<ClientToServerEvents, ServerToClientEvents> {
  if (io) {
    logger.warn('Socket.IO already initialized — returning existing instance');
    return io;
  }

  const corsOrigins = [
    'http://localhost:3000',
    'http://localhost:5173',
    ...(env.SOCKET_CORS_ORIGIN ? parseOrigins(env.SOCKET_CORS_ORIGIN) : parseOrigins(env.FRONTEND_URL)),
  ];

  io = new SocketIOServer<ClientToServerEvents, ServerToClientEvents>(httpServer, {
    cors: {
      origin: (origin, callback) => {
        if (!origin) return callback(null, true);
        callback(null, isAllowedSocketOrigin(origin, corsOrigins));
      },
      methods: ['GET', 'POST'],
      credentials: true,
    },
    // Production-safe settings:
    // websocket first for lower latency, polling fallback for restricted networks
    transports: ['websocket', 'polling'],
    pingTimeout: 30000,
    pingInterval: 12000,
    maxHttpBufferSize: 1e6,
    // Allow upgrades from polling to websocket
    allowUpgrades: true,
    // Cookie settings for sticky sessions
    cookie: {
      name: 'vedaai-socket',
      httpOnly: true,
      sameSite: 'lax',
      secure: env.NODE_ENV === 'production',
    },
  });

  io.on('connection', (socket) => {
    logger.debug(`Socket connected: ${socket.id} (transport: ${socket.conn.transport.name})`);
    let subscribeCount = 0;
    let windowStart = Date.now();

    const canSubscribe = (): boolean => {
      const now = Date.now();
      if (now - windowStart > SUBSCRIBE_WINDOW_MS) {
        windowStart = now;
        subscribeCount = 0;
      }
      subscribeCount += 1;
      return subscribeCount <= MAX_SUBSCRIBES_PER_WINDOW;
    };

    socket.on('subscribe:assignment', ({ assignmentId }) => {
      if (!canSubscribe()) {
        logger.warn(`Socket ${socket.id} exceeded subscribe rate limit and was disconnected`);
        socket.disconnect(true);
        return;
      }
      if (!isValidAssignmentId(assignmentId)) {
        logger.warn(`Socket ${socket.id} attempted invalid assignment subscription: ${String(assignmentId)}`);
        return;
      }
      if (socket.rooms.size > MAX_ROOMS_PER_SOCKET) {
        logger.warn(`Socket ${socket.id} exceeded room cap and was disconnected`);
        socket.disconnect(true);
        return;
      }
      const normalized = assignmentId.trim();
      socket.join(`assignment:${normalized}`);
      logger.debug(`Socket ${socket.id} subscribed to assignment:${normalized}`);
    });

    socket.on('unsubscribe:assignment', ({ assignmentId }) => {
      if (!isValidAssignmentId(assignmentId)) return;
      const normalized = assignmentId.trim();
      socket.leave(`assignment:${normalized}`);
      logger.debug(`Socket ${socket.id} unsubscribed from assignment:${normalized}`);
    });

    socket.on('disconnect', (reason) => {
      logger.debug(`Socket disconnected: ${socket.id} (${reason})`);
    });
  });

  return io;
}

export function getSocketServer(): SocketIOServer<ClientToServerEvents, ServerToClientEvents> {
  if (!io) throw new Error('Socket server not initialized');
  return io;
}

export function emitToAssignment<E extends keyof ServerToClientEvents>(
  assignmentId: string,
  event: E,
  payload: Parameters<ServerToClientEvents[E]>[0]
): void {
  if (!io) return;
  (io.to(`assignment:${assignmentId}`) as { emit: (ev: string, data: unknown) => void }).emit(event as any, payload);
}

export function emitToConversation(
  conversationId: string,
  event: string,
  payload: any
): void {
  if (!io) return;
  io.to(`conversation:${conversationId}`).emit(event as any, payload);
}

